import json
from datetime import timezone
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE, MISSING_TZ_POLICY
from window_projection import parse_bound


def _error(param, message, payload):
    return build_rejection(param, message, payload)


def _parse_bound(payload, param, errors):
    """Parse one bound and report malformed values without aborting the item."""
    if param not in payload:
        errors.append(_error(param, "is required", {"value": None}))
        return None

    value = payload[param]
    if not isinstance(value, str) or not value.strip():
        errors.append(_error(param, "must be a non-empty ISO 8601 string", {"value": value}))
        return None

    try:
        return parse_bound(value)
    except (TypeError, ValueError):
        errors.append(_error(param, "must be a valid ISO 8601 timestamp", {"value": value}))
        return None


def _comparison_payload(payload, start, end):
    return {
        "start_date": payload.get("start_date"),
        "end_date": payload.get("end_date"),
        "start_utc": start.astimezone(timezone.utc).isoformat(),
        "end_utc": end.astimezone(timezone.utc).isoformat(),
        "naive_timezone": MISSING_TZ_POLICY,
        "default_timezone": str(DEFAULT_TIMEZONE),
    }


def validate_range(payload):
    if not isinstance(payload, dict):
        return [_error("query", "must be an object", {"value": payload})]

    errors = []
    start = _parse_bound(payload, "start_date", errors)

    # end_date is optional: a start-only query is valid as long as its start
    # timestamp is valid.
    if "end_date" not in payload:
        return errors

    end = _parse_bound(payload, "end_date", errors)
    if start is None or end is None:
        return errors

    comparison = _comparison_payload(payload, start, end)
    start_utc = start.astimezone(timezone.utc)
    end_utc = end.astimezone(timezone.utc)
    if end_utc < start_utc:
        errors.append(_error("date_range", "end must not be before start after UTC normalization", comparison))

    # During a fall-back overlap, the same local hour occurs at two offsets.
    # The service rejects the ambiguous wall-clock ordering even where the
    # corresponding UTC instants happen to be ordered normally.
    different_offsets = start.utcoffset() != end.utcoffset()
    same_local_date = start.date() == end.date()
    same_local_hour = start.hour == end.hour
    local_end_before_start = end.replace(tzinfo=None) < start.replace(tzinfo=None)
    if different_offsets and same_local_date and same_local_hour and local_end_before_start:
        errors.append(_error("date_range", "ambiguous fall-back DST range has an earlier local end time", comparison))

    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

